use vstd::prelude::*;

verus! {

    // Constructs a new Vec of i32, of the same length as `a`, filled with zeros.
    // Ensures:
    // 1. The result has the same length as `a`.
    // 2. Every element of the result is 0.
    // 3. For any other Vec `b` of the same length, element‐wise addition with the zero‐vector
    //    leaves `b` unchanged (both on the left and on the right).
    fn zeros_like(a: &Vec<i32>) -> Vec<i32>
        ensures
            // (1) same length
            result.len() == a.len(),

            // (2) every element is zero
            forall idx: nat :: idx < a.len() ==> result[idx] == 0,

            // (3) adding the zero‐vector to any b of same length yields b
            forall idx: nat, b: &Vec<i32> ::
                b.len() == a.len() && idx < a.len() ==>
                b[idx] + result[idx] == b[idx] &&
                result[idx] + b[idx] == b[idx]
    {
        // We'll build up `z` element by element
        let mut z: Vec<i32> = Vec::<i32>::new();
        let mut i: usize = 0;

        // Loop to push a zero for each element of `a`
        while i < a.len()
            invariant
                // `z` has grown exactly to length `i`
                z.len() == i,

                // all elements so far are zero
                forall j: nat :: j < z.len() ==> z[j] == 0,

                // `i` never exceeds `a.len()`
                i <= a.len(),
            decreases a.len() - i
        {
            z.push(0);
            i += 1;
        }

        // At this point i == a.len(), so z.len() == a.len() and all entries are zero
        z
    }

}

